<div id="narr" style="font-size:11px;line-height:1.45;color:#333"></div>
<div style="font-size:10px;color:#666;line-height:1.4">Drag to orbit: the “parallelograms” are flat square embedding planes stacked in depth.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ---------------- element spec ----------------------------------------------
 * embedding plane   → 4 thin CylinderGeometry edges (#4a4a4a) + LineSegments 4x4 grid (#dcdcdc), flat in XZ
 * image marker      → Sprite w/ CanvasTexture glyph (circle / square / triangle) in concept colour, 0.30u
 * text item         → Sprite w/ CanvasTexture sans-serif string ("blue triangle"), 0.28u tall
 * trajectory        → THREE.Line + LineDashedMaterial (concept colour left, #555 right), 5 pts, computeLineDistances
 * encoder arrow     → Group: CylinderGeometry shaft + ConeGeometry head, black
 * block box         → ShapeGeometry white fill + LineLoop rounded-rect outline + monospace text Sprite
 * encoder rule      → thin Cylinder, black, + rotated HTML addLabel caption (serif)
 * joint disk        → Sprite w/ CanvasTexture filled circle #F4A582 + black ring, r≈1.2
 * joint arrows      → 2 diagonal Cylinder+Cone arrows into the disk rim
 * pick proxy        → invisible (opacity-0) SphereGeometry at every marker / text anchor
 * ---------------------------------------------------------------------------*/

/* ---- screen-aligned layout basis (keeps both columns level under isometric) */
const U    = new THREE.Vector3(1, 0, -1).normalize();   // projects to screen-right
const WDIR = new THREE.Vector3(1, 0,  1).normalize();   // projects straight down
const YUP  = new THREE.Vector3(0, 1, 0);
const BASIS_Q = new THREE.Quaternion().setFromRotationMatrix(
  new THREE.Matrix4().makeBasis(U, YUP, WDIR));
function P(X, Y, D = 0) {
  return new THREE.Vector3(U.x * X + WDIR.x * D, Y, U.z * X + WDIR.z * D);
}

const LEVELS = 5, YSTEP = 4.8, HALF = 2.0;
const LY = L => YSTEP * L;
const LXf = L => -4.0 + 0.35 * L;
const RXf = L =>  4.0 + 0.35 * L;

/* ---- concepts --------------------------------------------------------------*/
const CONCEPTS = [
  { id: 'red circle',      shape: 'circle',   color: '#E8746B' },
  { id: 'pink circle',     shape: 'circle',   color: '#F58CB6' },
  { id: 'purple circle',   shape: 'circle',   color: '#B3A4E0' },
  { id: 'orange circle',   shape: 'circle',   color: '#F3A76A' },
  { id: 'blue circle',     shape: 'circle',   color: '#5BC8E8' },
  { id: 'pink square',     shape: 'square',   color: '#F776CE' },
  { id: 'green square',    shape: 'square',   color: '#55C98B' },
  { id: 'blue triangle',   shape: 'triangle', color: '#3AAEE0' },
  { id: 'purple triangle', shape: 'triangle', color: '#A79BE0' },
];
const TARGET = [[-1.5,0.6],[-0.9,1.05],[-1.6,-0.1],[-0.8,0.25],[-1.3,1.35],
                [0.95,1.2],[1.5,0.5],[1.2,-1.2],[0.4,-1.05]];

function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);
  t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
const rnd = mulberry32(20240517);
const clamp = v => Math.max(-1.75, Math.min(1.75, v));

const positions = [[], []];
for (let b = 0; b < 2; b++) {
  const start = CONCEPTS.map(() => [(rnd()*2-1)*1.55, (rnd()*2-1)*1.55]);
  const tgt = CONCEPTS.map((c, i) => {
    const [tx, ty] = TARGET[i];
    if (b === 0) return [tx, ty];
    const a = 0.15;
    return [tx*Math.cos(a) - ty*Math.sin(a) + 0.12, tx*Math.sin(a) + ty*Math.cos(a) - 0.08];
  });
  for (let L = 0; L < LEVELS; L++) {
    const t = L / (LEVELS - 1), e = t * t;
    positions[b][L] = CONCEPTS.map((c, i) => [
      clamp(start[i][0]*(1-e) + tgt[i][0]*e + (rnd()*2-1)*0.62*(1-e)),
      clamp(start[i][1]*(1-e) + tgt[i][1]*e + (rnd()*2-1)*0.62*(1-e)),
    ]);
  }
}

/* ---- fade registry (drives every opacity tween) ---------------------------*/
const fadeReg = [];
function reg(mat, base = 1) {
  mat.transparent = true;
  const e = { mat, target: base, cur: base, base };
  fadeReg.push(e); return e;
}
function regDiv(div) { const e = { div, target: 1, cur: 1 }; fadeReg.push(e); return e; }

/* ---- geometry helpers -----------------------------------------------------*/
function makeCyl(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a), len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8, 1), mat);
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(YUP, dir.clone().normalize());
  return m;
}
function makeArrow(a, b, mat, r = 0.075) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(b, a), len = dir.length();
  const n = dir.clone().normalize();
  const hl = Math.min(0.72, len * 0.42), hr = r * 3.1;
  const se = b.clone().addScaledVector(n, -hl);
  g.add(makeCyl(a, se, r, mat));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(hr, hl, 16), mat);
  cone.position.copy(se).addScaledVector(n, hl / 2);
  cone.quaternion.setFromUnitVectors(YUP, n);
  g.add(cone);
  return g;
}
function roundRectPts(w, h, r, seg = 6) {
  const pts = [], hw = w/2 - r, hh = h/2 - r;
  const corners = [[hw,hh,0],[-hw,hh,Math.PI/2],[-hw,-hh,Math.PI],[hw,-hh,3*Math.PI/2]];
  for (const [cx, cy, a0] of corners)
    for (let i = 0; i <= seg; i++) {
      const a = a0 + (Math.PI/2) * (i/seg);
      pts.push(new THREE.Vector2(cx + r*Math.cos(a), cy + r*Math.sin(a)));
    }
  return pts;
}
const _texCache = new Map();
function markerTexture(cpt) {
  if (_texCache.has(cpt.id)) return _texCache.get(cpt.id);
  const s = 96, c = document.createElement('canvas'); c.width = c.height = s;
  const x = c.getContext('2d');
  x.fillStyle = cpt.color; x.strokeStyle = 'rgba(70,70,70,0.6)'; x.lineWidth = 5;
  const m = 13;
  if (cpt.shape === 'circle') { x.beginPath(); x.arc(s/2, s/2, s/2 - m, 0, Math.PI*2); x.fill(); x.stroke(); }
  else if (cpt.shape === 'square') { x.beginPath(); x.rect(m, m, s-2*m, s-2*m); x.fill(); x.stroke(); }
  else { x.beginPath(); x.moveTo(s/2, m); x.lineTo(s-m, s-m*1.25); x.lineTo(m, s-m*1.25); x.closePath(); x.fill(); x.stroke(); }
  const t = new THREE.CanvasTexture(c); t.minFilter = THREE.LinearFilter;
  _texCache.set(cpt.id, t); return t;
}
const _txtCache = new Map();
function textTexture(text, opt) {
  const key = text + '|' + JSON.stringify(opt);
  if (_txtCache.has(key)) return _txtCache.get(key);
  const fontPx = opt.fontPx || 48;
  const fam = opt.mono ? 'ui-monospace, Consolas, monospace'
            : opt.serif ? 'Georgia, serif' : 'Helvetica, Arial, sans-serif';
  const font = (opt.bold ? 'bold ' : '') + fontPx + 'px ' + fam;
  const meas = document.createElement('canvas').getContext('2d'); meas.font = font;
  const w = Math.ceil(meas.measureText(text).width) + 12, h = Math.ceil(fontPx * 1.4);
  const c = document.createElement('canvas'); c.width = w; c.height = h;
  const x = c.getContext('2d');
  x.font = font; x.textAlign = 'center'; x.textBaseline = 'middle';
  x.fillStyle = opt.color || '#1a1a1a';
  x.fillText(text, w/2, h/2);
  const t = new THREE.CanvasTexture(c); t.minFilter = THREE.LinearFilter;
  t.userData = { w, h };
  _txtCache.set(key, t); return t;
}
function makeTextSprite(text, opt = {}) {
  const tex = textTexture(text, opt);
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: false });
  const sp = new THREE.Sprite(mat);
  const hgt = opt.height || 0.3;
  sp.scale.set(hgt * tex.userData.w / tex.userData.h, hgt, 1);
  sp.renderOrder = 6;
  return sp;
}
function makeMarkerSprite(cpt, size = 0.32) {
  const mat = new THREE.SpriteMaterial({ map: markerTexture(cpt), transparent: true, depthWrite: false, depthTest: false });
  const sp = new THREE.Sprite(mat);
  sp.scale.set(size, size, 1); sp.renderOrder = 6;
  return sp;
}

/* ---- scene root -----------------------------------------------------------*/
const gRoot = new THREE.Group(); scene.add(gRoot);
const pickMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
const pickGeo = new THREE.SphereGeometry(0.33, 8, 6);
const pickList = [];
const allItems = [];

const branchDefs = [
  { key: 'image', xAt: LXf, boxX: -8.2, boxText: 'ViT block x3',
    ruleX: -11.2, ruleText: 'Image encoder', sign: -1 },
  { key: 'text',  xAt: RXf, boxX: 10.8, boxText: 'transformer block x3',
    ruleX: 13.8, ruleText: 'Text encoder', sign: 1 },
];

const branches = branchDefs.map((def, bi) => {
  const group = new THREE.Group(); gRoot.add(group);
  const planes = [], items = [], trajs = [], extras = [], divs = [];

  /* planes */
  for (let L = 0; L < LEVELS; L++) {
    const c = P(def.xAt(L), LY(L));
    const om = new THREE.MeshBasicMaterial({ color: 0x4a4a4a, transparent: true, depthWrite: false });
    const gm = new THREE.LineBasicMaterial({ color: 0xdcdcdc, transparent: true, depthWrite: false });
    const pg = new THREE.Group(); pg.position.copy(c); group.add(pg);
    const cs = [new THREE.Vector3(-HALF,0,-HALF), new THREE.Vector3(HALF,0,-HALF),
                new THREE.Vector3(HALF,0,HALF), new THREE.Vector3(-HALF,0,HALF)];
    for (let i = 0; i < 4; i++) pg.add(makeCyl(cs[i], cs[(i+1)%4], 0.035, om));
    const gp = [];
    for (let i = 1; i < 4; i++) {
      const t = -HALF + i * (2*HALF/4);
      gp.push(new THREE.Vector3(t,0,-HALF), new THREE.Vector3(t,0,HALF),
              new THREE.Vector3(-HALF,0,t), new THREE.Vector3(HALF,0,t));
    }
    pg.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(gp), gm));
    planes.push({ group: pg, center: c, e: [reg(om), reg(gm, 0.9)] });
  }

  /* markers / text items + pick proxies */
  for (let L = 0; L < LEVELS; L++) {
    items[L] = CONCEPTS.map((cpt, i) => {
      const [a, z] = positions[bi][L][i];
      const pos = planes[L].center.clone().add(new THREE.Vector3(a, 0.06, z));
      const sp = bi === 0 ? makeMarkerSprite(cpt)
                          : makeTextSprite(cpt.id, { fontPx: 46, height: 0.28, color: '#1a1a1a' });
      sp.position.copy(pos); group.add(sp);
      const proxy = new THREE.Mesh(pickGeo, pickMat);
      proxy.position.copy(pos); proxy.scale.setScalar(bi === 0 ? 1 : 1.5);
      group.add(proxy);
      registerInteractive(proxy, {
        title: cpt.id + ' — ' + (bi === 0 ? 'image branch' : 'text branch') + ', layer ' + (L + 1),
        tooltip: cpt.id + ' · ' + (bi === 0 ? 'image' : 'text') + ' layer ' + (L + 1),
        body: 'This is the ' + (bi === 0 ? 'visual' : 'textual') + ' embedding of “' + cpt.id +
              '” after ' + (L * 3) + ' ' + (bi === 0 ? 'ViT' : 'transformer') + ' blocks. ' +
              'Follow the dashed chain upward: by the top plane its position mirrors the same concept in the other modality.'
      });
      pickList.push({ obj: proxy, concept: i, level: L, branch: bi });
      const rec = { sp, e: reg(sp.material), base: sp.scale.clone(), tgtScale: sp.scale.clone(), pos, proxy, level: L };
      allItems.push(rec);
      return rec;
    });
  }

  /* trajectories */
  CONCEPTS.forEach((cpt, i) => {
    const pts = [];
    for (let L = 0; L < LEVELS; L++) pts.push(items[L][i].pos.clone().add(new THREE.Vector3(0, 0.01, 0)));
    const mat = new THREE.LineDashedMaterial({
      color: new THREE.Color(bi === 0 ? cpt.color : '#555555'),
      dashSize: 0.26, gapSize: 0.18, transparent: true, opacity: 0.28, depthWrite: false });
    const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
    line.computeLineDistances(); line.renderOrder = 3; group.add(line);
    trajs.push({ line, e: reg(mat, 0.28) });
  });

  /* arrows + rounded block boxes */
  const blackMat = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true });
  const lineBlack = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true });
  const whiteMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, side: THREE.DoubleSide });
  extras.push(reg(blackMat), reg(lineBlack), reg(whiteMat));

  for (let L = 0; L < LEVELS - 1; L++) {
    const y0 = LY(L);
    group.add(makeArrow(P(def.boxX, y0 + 2.75), P(def.boxX, y0 + 4.35), blackMat, 0.08));
    const ts = makeTextSprite(def.boxText, { fontPx: 44, height: 0.32, mono: true, color: '#000' });
    const bw = ts.scale.x + 0.55, bh = 0.95;
    ts.position.copy(P(def.boxX, y0 + 1.55, 0.05)); group.add(ts);
    extras.push(reg(ts.material));
    const pts2 = roundRectPts(bw, bh, 0.3);
    const shape = new THREE.Shape(pts2);
    const fill = new THREE.Mesh(new THREE.ShapeGeometry(shape), whiteMat);
    fill.quaternion.copy(BASIS_Q); fill.position.copy(P(def.boxX, y0 + 1.55, -0.05));
    group.add(fill);
    const outline = new THREE.LineLoop(
      new THREE.BufferGeometry().setFromPoints(pts2.map(p => new THREE.Vector3(p.x, p.y, 0))), lineBlack);
    outline.quaternion.copy(BASIS_Q); outline.position.copy(P(def.boxX, y0 + 1.55));
    group.add(outline);
  }

  /* encoder rule + rotated caption */
  group.add(makeCyl(P(def.ruleX, -2.0), P(def.ruleX, LY(4) + 2.4), 0.03, blackMat));
  const cap = addLabel(
    '<span style="display:inline-block;transform:rotate(-90deg)">' + def.ruleText + '</span>',
    P(def.ruleX + def.sign * 0.85, LY(2)), { fontSize: '17px' });
  cap.div.style.fontFamily = 'Georgia, serif';
  divs.push(regDiv(cap.div));

  return { key: def.key, group, planes, items, trajs, extras, divs };
});

/* ---- joint embedding space ------------------------------------------------*/
const jointE = [];
(function buildJoint() {
  const s = 256, c = document.createElement('canvas'); c.width = c.height = s;
  const x = c.getContext('2d');
  x.fillStyle = '#F4A582'; x.strokeStyle = '#000'; x.lineWidth = 6;
  x.beginPath(); x.arc(s/2, s/2, s/2 - 6, 0, Math.PI*2); x.fill(); x.stroke();
  const tex = new THREE.CanvasTexture(c); tex.minFilter = THREE.LinearFilter;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: false });
  const sp = new THREE.Sprite(mat);
  sp.scale.set(2.4, 2.4, 1); sp.position.copy(P(0, 22.9)); sp.renderOrder = 7;
  gRoot.add(sp);
  window.__disk = sp;
  registerInteractive(sp, {
    title: 'Joint embedding space',
    tooltip: 'Joint embedding space',
    body: 'Both encoders project into this single shared space. Only here can an image vector and a text vector be compared with a dot product — which is exactly what the contrastive CLIP loss optimises.'
  });
  const jm = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.18 });
  jointE.push(reg(jm, 1));
  gRoot.add(makeArrow(P(-2.9, 20.3), P(-1.35, 21.85), jm, 0.085));
  gRoot.add(makeArrow(P( 2.9, 20.3), P( 1.35, 21.85), jm, 0.085));
  const t = addLabel('Joint embedding space', P(0, 25.6), { fontSize: '22px' });
  t.div.style.fontFamily = 'Georgia, serif';
})();

/* ---- camera (after all geometry) -----------------------------------------*/
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.72 });
document.getElementById('btnReset').style.display = '';

/* ---- state + refresh ------------------------------------------------------*/
const STEPS = ['input', 'layer 2', 'layer 3', 'layer 4', 'layer 5', 'joint space'];
const state = { step: 0, branch: 'both', highlight: null, pinned: null };

function branchFactor(bi) {
  if (state.branch === 'both') return 1;
  return (state.branch === 'image' && bi === 0) || (state.branch === 'text' && bi === 1) ? 1 : 0.08;
}
function refresh() {
  const vis = Math.min(state.step, 4);
  const joint = state.step === 5;
  branches.forEach((B, bi) => {
    const bf = branchFactor(bi);
    B.planes.forEach((p, L) => {
      const lf = L <= vis ? 1 : 0.15;
      p.e[0].target = bf * lf;
      p.e[1].target = bf * lf * 0.9;
    });
    B.items.forEach((row, L) => row.forEach((it, i) => {
      const on = L <= vis ? 1 : 0;
      const h = state.highlight == null ? 1 : (state.highlight === i ? 1 : 0.28);
      it.e.target = bf * on * h;
      it.tgtScale.copy(it.base).multiplyScalar(state.highlight === i ? 1.55 : 1);
      it.proxy.visible = on > 0 && bf > 0.5;
    }));
    B.trajs.forEach((tr, i) => {
      tr.line.geometry.setDrawRange(0, vis + 1);
      const h = state.highlight == null ? 0.3 : (state.highlight === i ? 0.95 : 0.07);
      tr.e.target = bf * h;
    });
    B.extras.forEach(e => { e.target = bf * e.base; });
    B.divs.forEach(e => { e.target = bf; });
  });
  jointE.forEach(e => { e.target = joint ? 1 : 0.18; });

  stepBtns.forEach((b, i) => b.classList.toggle('active', i === state.step));
  bvBtns.forEach(([b, k]) => b.classList.toggle('active', state.branch === k));
  legBtns.forEach((b, i) => b.classList.toggle('active', state.pinned === i));
}

/* ---- UI wiring ------------------------------------------------------------*/
const stepRow = document.getElementById('stepRow');
const stepBtns = STEPS.map((s, i) => {
  const b = document.createElement('button');
  b.textContent = s; b.style.padding = '3px 6px';
  b.addEventListener('click', () => { stopDemo(); state.step = i; refresh(); });
  stepRow.appendChild(b); return b;
});
document.getElementById('btnNext').addEventListener('click', () => {
  stopDemo(); state.step = Math.min(5, state.step + 1); refresh();
});
document.getElementById('btnPrev').addEventListener('click', () => {
  stopDemo(); state.step = Math.max(0, state.step - 1); refresh();
});
const bvBtns = [
  [document.getElementById('bvImage'), 'image'],
  [document.getElementById('bvText'), 'text'],
  [document.getElementById('bvBoth'), 'both'],
];
bvBtns.forEach(([b, k]) => b.addEventListener('click', () => { stopDemo(); state.branch = k; refresh(); }));

const legend = document.getElementById('legend');
const legBtns = CONCEPTS.map((c, i) => {
  const b = document.createElement('button');
  b.innerHTML = '<span style="display:inline-block;width:8px;height:8px;border-radius:' +
    (c.shape === 'circle' ? '50%' : '1px') + ';background:' + c.color +
    ';margin-right:4px"></span>' + c.id;
  b.style.padding = '2px 5px'; b.style.fontSize = '10px';
  b.addEventListener('mouseenter', () => { if (state.pinned == null) { state.highlight = i; refresh(); } });
  b.addEventListener('mouseleave', () => { if (state.pinned == null) { state.highlight = null; refresh(); } });
  b.addEventListener('click', () => { state.pinned = state.pinned === i ? null : i; state.highlight = state.pinned; refresh(); });
  legend.appendChild(b); return b;
});
document.getElementById('btnClearHl').addEventListener('click', () => {
  state.pinned = null; state.highlight = null; refresh();
});

/* ---- hover highlighting on the figure ------------------------------------*/
const figRay = new THREE.Raycaster(), figPtr = new THREE.Vector2();
canvas.addEventListener('pointermove', (ev) => {
  if (state.pinned != null) return;
  const r = canvas.getBoundingClientRect();
  figPtr.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  figPtr.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  figRay.setFromCamera(figPtr, camera);
  const objs = pickList.filter(p => p.obj.visible).map(p => p.obj);
  const hit = figRay.intersectObjects(objs, false)[0];
  let h = null;
  if (hit) { const rec = pickList.find(p => p.obj === hit.object); if (rec) h = rec.concept; }
  if (h !== state.highlight) { state.highlight = h; refresh(); }
});
canvas.addEventListener('pointerleave', () => {
  if (state.pinned == null && state.highlight != null) { state.highlight = null; refresh(); }
});

/* ---- demo walkthrough -----------------------------------------------------*/
const DEMO = [
  { title: 'Raw inputs', n: 'At the bottom plane the image markers and the text labels sit in unrelated, modality-specific arrangements — a pink square and the string “pink square” land nowhere near analogous spots.', s: { step: 0, branch: 'both' } },
  { title: 'After the first ViT / transformer blocks', n: 'One step up, each branch has been reshuffled by its own three blocks. Colours begin to cluster on the left; object-name labels begin to group on the right.', s: { step: 1, branch: 'both' } },
  { title: 'Image branch in isolation', n: 'Hiding the text stack shows that the left transformations are purely visual: shapes and hues migrate only relative to one another, with no reference to language.', s: { step: 2, branch: 'image' } },
  { title: 'Text branch in isolation', n: 'The same middle layer on the right: the label layout reorganises by its own transformer blocks, independent of any image.', s: { step: 2, branch: 'text' } },
  { title: 'Layouts converge', n: 'By the top planes the two arrangements are near mirror images — “blue triangle” sits in the same relative region as the blue triangle marker.', s: { step: 4, branch: 'both' } },
  { title: 'Joint embedding space', n: 'Both arrows fire into the orange disk: only here are image and text vectors compared directly, which is what the contrastive objective trains.', s: { step: 5, branch: 'both' } },
];
const narrT = document.getElementById('narrTitle'), narrB = document.getElementById('narr');
let demoTimer = null, demoIdx = 0;
function goToStep(i) {
  const d = DEMO[i]; if (!d) return;
  state.step = d.s.step; state.branch = d.s.branch;
  if (i === 4) { state.pinned = 7; state.highlight = 7; }   // blue triangle
  else if (i === 5) { state.pinned = null; state.highlight = null; }
  narrT.textContent = (i + 1) + '/' + DEMO.length + '  ' + d.title;
  narrB.textContent = d.n;
  refresh();
}
function stopDemo() {
  if (demoTimer) { clearInterval(demoTimer); demoTimer = null; document.getElementById('btnDemo').textContent = '▶ play walkthrough'; }
}
document.getElementById('btnDemo').addEventListener('click', () => {
  if (demoTimer) { stopDemo(); return; }
  demoIdx = 0; goToStep(0);
  document.getElementById('btnDemo').textContent = '⏹ stop walkthrough';
  demoTimer = setInterval(() => {
    demoIdx++;
    if (demoIdx >= DEMO.length) { stopDemo(); return; }
    goToStep(demoIdx);
  }, 4200);
});

/* ---- tween loop -----------------------------------------------------------*/
