/* ---- screen-aligned layout basis (isometric: U projects exactly horizontal) */
const U    = new THREE.Vector3(1, 0, -1).normalize();
const WDIR = new THREE.Vector3(1, 0,  1).normalize();
const YUP  = new THREE.Vector3(0, 1, 0);
const BASIS_Q = new THREE.Quaternion().setFromRotationMatrix(
  new THREE.Matrix4().makeBasis(U, YUP, WDIR));
const ELEV = THREE.MathUtils.degToRad(35.264389682754654);
const VCOMP = 1 / Math.cos(ELEV);           // un-foreshorten upright rectangles
function P(X, Y, D = 0) {
  return new THREE.Vector3(U.x * X + WDIR.x * D, Y, U.z * X + WDIR.z * D);
}

/* ---- world-scale layout ---------------------------------------------------*/
const LEVELS = 5, YSTEP = 4.8, HALF = 2.0;
const LY  = L => YSTEP * L;
const LXf = L => -4.0 + 0.35 * L;
const RXf = L =>  4.0 + 0.35 * L;
const COL   = 9.3;          // block-box / arrow column (screen-X)
const RULEX = 12.6;         // encoder rules
const DISK_Y = 23.6, DISK_R = 1.25;

/* ---- concepts --------------------------------------------------------------*/
const CONCEPTS = [
  { id: 'red circle',      shape: 'circle',   color: '#E8746B' },
  { id: 'pink circle',     shape: 'circle',   color: '#F58CB6' },
  { id: 'purple circle',   shape: 'circle',   color: '#B3A4E0' },
  { id: 'orange circle',   shape: 'circle',   color: '#F3A76A' },
