const LY  = L => YSTEP * L;
const LXf = L => -4.0 + 0.35 * L;
const RXf = L =>  4.0 + 0.35 * L;
const COL   = 9.3;          // block-box / arrow column (screen-X)
const RULEX = 12.6;         // encoder rules
